@pytest.mark.parametrize('operation', ['modify', 'cancel', 'snapshot']) def test_B24_native_finite_echo_accepts_exact_STP_modify_cancel_and_snapshot(tmp_path, monkeypatch, operation): rig, pid, adapter = _pending_rig(tmp_path, monkeypatch) trade = _native(rig) adapter._trades[REF] = trade; adapter.ib.snapshot = [trade] if operation == 'modify': req = ProtectionRequest(REF, pid, 'AAPL', 2, STOP, None, broker_order_id=64, perm_id=PERM_ID, con_id=CON_ID, client_id=CLIENT_ID, account=rig.cfg.account, allow_lookup=False) adapter.modify_protection(req) [(_, wire)] = adapter.ib.placed assert wire.orderType == 'STP' and wire.auxPrice == STOP and wire.totalQuantity == 2 assert wire.lmtPrice == sys.float_info.max, 'echo must never be sent as an actual stop limit' assert adapter.ib.cancelled == [] elif operation == 'cancel': adapter.cancel(REF, expected_order_id=64, expected_perm_id=PERM_ID, expected_con_id=CON_ID, allow_lookup=False) assert len(adapter.ib.cancelled) == 1 and adapter.ib.placed == [] else: [snapshot] = adapter.open_orders() > assert snapshot.limit_price is None E AssertionError: assert 340.19000000000005 is None E + where 340.19000000000005 = OpenOrder(intent_id='v6l-protect-3255088aaf6c4956b4bc', broker_order_id=64, symbol='AAPL', status='PreSubmitted', fill...f='GTC', aux_price=340.22, limit_price=340.19000000000005, outside_rth=False, account='DU0000001', total_quantity=None).limit_price
